29	import * as zrUtil from 'zrender/src/core/util';
30	
31	const RADIAN_EPSILON = 1e-4;
32	// Although chrome already enlarge this number to 100 for `toFixed`, but
33	// we sill follow the spec for compatibility.
34	const ROUND_SUPPORTED_PRECISION_MAX = 20;
35	
36	function _trim(str: string): string {
37	    return str.replace(/^\s+|\s+$/g, '');
38	}
39	
40	export const mathMin = Math.min;
41	export const mathMax = Math.max;
42	export const mathAbs = Math.abs;
43	
44	/**
45	 * Linear mapping a value from domain to range
46	 * @param  val
47	 * @param  domain Domain extent domain[0] can be bigger than domain[1]
48	 * @param  range  Range extent range[0] can be bigger than range[1]
49	 * @param  clamp Default to be false
50	 */
51	export function linearMap(
52	    val: number,
53	    domain: number[],
54	    range: number[],
55	    clamp?: boolean
56	): number {
57	    const d0 = domain[0];
58	    const d1 = domain[1];
59	    const r0 = range[0];
60	    const r1 = range[1];
61	
62	    const subDomain = d1 - d0;
63	    const subRange = r1 - r0;
64	
65	    if (subDomain === 0) {
66	        return subRange === 0
67	            ? r0
68	            : (r0 + r1) / 2;
69	    }
70	
71	    // Avoid accuracy problem in edge, such as
72	    // 146.39 - 62.83 === 83.55999999999999.
73	    // See echarts/test/ut/spec/util/number.js#linearMap#accuracyError
74	    // It is a little verbose for efficiency considering this method
75	    // is a hotspot.
76	    if (clamp) {
77	        if (subDomain > 0) {
78	            if (val <= d0) {
79	                return r0;
80	            }
81	            else if (val >= d1) {
82	                return r1;
83	            }
84	        }
85	        else {
86	            if (val >= d0) {
87	                return r0;
88	            }
89	            else if (val <= d1) {
90	                return r1;
91	            }
92	        }
93	    }
94	    else {
95	        if (val === d0) {
96	            return r0;
97	        }
98	        if (val === d1) {
99	            return r1;
100	        }
101	    }
102	
103	    return (val - d0) / subDomain * subRange + r0;
104	}
105	
106	/**
107	 * Preserve the name `parsePercent` for backward compatibility,
108	 * and it's effectively published as `echarts.number.parsePercent`.
109	 */
110	export const parsePercent = parsePositionOption;
111	
112	/**
113	 * @see {parsePositionSizeOption} and also accept a string preset.
114	 * @see {PositionSizeOption}
115	 */
116	export function parsePositionOption(option: unknown, percentBase: number, percentOffset?: number): number {
117	    switch (option) {
118	        case 'center':
119	        case 'middle':
120	            option = '50%';
121	            break;
122	        case 'left':
