239	/**
240	 * Get a data of given precision, assuring the sum of percentages
241	 * in valueList is 1.
242	 * The largest remainder method is used.
243	 * https://en.wikipedia.org/wiki/Largest_remainder_method
244	 *
245	 * @param valueList a list of all data
246	 * @param idx index of the data to be processed in valueList
247	 * @param precision integer number showing digits of precision
248	 * @return percent ranging from 0 to 100
249	 */
250	export function getPercentWithPrecision(valueList: number[], idx: number, precision: number): number {
251	    if (!valueList[idx]) {
252	        return 0;
253	    }
254	
255	    const seats = getPercentSeats(valueList, precision);
256	
257	    return seats[idx] || 0;
258	}
