260	/**
261	 * Get a data of given precision, assuring the sum of percentages
262	 * in valueList is 1.
263	 * The largest remainder method is used.
264	 * https://en.wikipedia.org/wiki/Largest_remainder_method
265	 *
266	 * @param valueList a list of all data
267	 * @param precision integer number showing digits of precision
268	 * @return {Array<number>}
269	 */
270	export function getPercentSeats(valueList: number[], precision: number): number[] {
271	    const sum = zrUtil.reduce(valueList, function (acc, val) {
272	        return acc + (isNaN(val) ? 0 : val);
273	    }, 0);
274	    if (sum === 0) {
275	        return [];
276	    }
277	
278	    const digits = Math.pow(10, precision);
279	    const votesPerQuota = zrUtil.map(valueList, function (val) {
280	        return (isNaN(val) ? 0 : val) / sum * digits * 100;
281	    });
282	    const targetSeats = digits * 100;
283	
284	    const seats = zrUtil.map(votesPerQuota, function (votes) {
285	        // Assign automatic seats.
286	        return Math.floor(votes);
287	    });
288	    let currentSum = zrUtil.reduce(seats, function (acc, val) {
289	        return acc + val;
290	    }, 0);
291	
292	    const remainder = zrUtil.map(votesPerQuota, function (votes, idx) {
293	        return votes - seats[idx];
294	    });
295	
296	    // Has remainding votes.
297	    while (currentSum < targetSeats) {
298	        // Find next largest remainder.
299	        let max = Number.NEGATIVE_INFINITY;
300	        let maxId = null;
301	        for (let i = 0, len = remainder.length; i < len; ++i) {
302	            if (remainder[i] > max) {
303	                max = remainder[i];
304	                maxId = i;
305	            }
306	        }
307	
308	        // Add a vote to max remainder.
309	        ++seats[maxId];
310	        remainder[maxId] = 0;
311	        ++currentSum;
312	    }
313	    return zrUtil.map(seats, function (seat) {
314	        return seat / digits;
315	    });
316	}
