465	/**
466	 * find a “nice” number approximately equal to x. Round the number if round = true,
467	 * take ceiling if round = false. The primary observation is that the “nicest”
468	 * numbers in decimal are 1, 2, and 5, and all power-of-ten multiples of these numbers.
469	 *
470	 * See "Nice Numbers for Graph Labels" of Graphic Gems.
471	 *
472	 * @param  val Non-negative value.
473	 * @param  round
474	 * @return Niced number
475	 */
476	export function nice(val: number, round?: boolean): number {
477	    const exponent = quantityExponent(val);
478	    const exp10 = Math.pow(10, exponent);
479	    const f = val / exp10; // 1 <= f < 10
480	    let nf;
481	    if (round) {
482	        if (f < 1.5) {
483	            nf = 1;
484	        }
485	        else if (f < 2.5) {
486	            nf = 2;
487	        }
488	        else if (f < 4) {
489	            nf = 3;
490	        }
491	        else if (f < 7) {
492	            nf = 5;
493	        }
494	        else {
495	            nf = 10;
496	        }
497	    }
498	    else {
499	        if (f < 1) {
500	            nf = 1;
501	        }
502	        else if (f < 2) {
503	            nf = 2;
504	        }
505	        else if (f < 3) {
506	            nf = 3;
507	        }
508	        else if (f < 5) {
509	            nf = 5;
510	        }
511	        else {
512	            nf = 10;
513	        }
514	    }
515	    val = nf * exp10;
516	
517	    // Fix 3 * 0.1 === 0.30000000000000004 issue (see IEEE 754).
518	    // 20 is the uppper bound of toFixed.
519	    return exponent >= -20 ? +val.toFixed(exponent < 0 ? -exponent : 0) : val;
520	}
