522	/**
523	 * This code was copied from "d3.js"
524	 * <https://github.com/d3/d3/blob/9cc9a875e636a1dcf36cc1e07bdf77e1ad6e2c74/src/arrays/quantile.js>.
525	 * See the license statement at the head of this file.
526	 * @param ascArr
527	 */
528	export function quantile(ascArr: number[], p: number): number {
529	    const H = (ascArr.length - 1) * p + 1;
530	    const h = Math.floor(H);
531	    const v = +ascArr[h - 1];
532	    const e = H - h;
533	    return e ? v + e * (ascArr[h] - v) : v;
534	}
